1	// A minimal fake browser for public/app.js: only the APIs the spec allows.
2	// Any other member the script touches is recorded in `page.violations` (and throws).
3	import { readFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import vm from 'node:vm';
6	import { ROOT } from './server.mjs';
7	
8	export const APP_PATH = join(ROOT, 'public', 'app.js');
9	
10	const ELEMENT_MEMBERS = new Set([
11	  'textContent', 'value', 'type', 'disabled', 'append', 'replaceChildren', 'addEventListener',
12	]);
13	const PAGE_ELEMENTS = [
14	  ['booking-form', 'form'], ['room', 'select'], ['title', 'input', 'text'], ['date', 'input', 'date'],
15	  ['start', 'input', 'time'], ['end', 'input', 'time'], ['book', 'button', 'submit'],
16	  ['filter-date', 'input', 'date'], ['show-all', 'button', 'button'], ['booking-list', 'ul'],
17	  ['error', 'p'],
18	];
19	
20	export class TextNode {
21	  constructor(data) {
22	    this.nodeType = 3;
23	    this.data = String(data);
24	  }
25	}
26	
27	/** Test-side element. The script only ever sees `el.proxy`. */
28	export class FakeElement {
29	  constructor(page, tag, { id = null, type = '' } = {}) {
30	    this.page = page;
31	    this.tag = tag;
32	    this.id = id;
33	    this.type = type;
34	    this.disabled = false;
35	    this.childNodes = [];
36	    this.listeners = {};
37	    this.storedValue = '';
38	    this.proxy = page.wrap(this, this.label(), ELEMENT_MEMBERS);
39	  }
40	
41	  label() {
42	    return this.id ? `#${this.id}` : `<${this.tag}>`;
43	  }
44	
45	  get value() {
46	    if (this.tag === 'select' && this.storedValue === '' && this.childNodes.length > 0) {
47	      return this.childNodes[0].value;
48	    }
49	    return this.storedValue;
50	  }
51	
52	  set value(v) {
53	    this.storedValue = String(v);
54	  }
55	
56	  get textContent() {
57	    return this.childNodes.map((n) => (n instanceof TextNode ? n.data : n.textContent)).join('');
58	  }
59	
60	  set textContent(v) {
61	    const text = String(v);
62	    this.childNodes = text === '' ? [] : [new TextNode(text)];
63	  }
64	
65	  get children() {
66	    return this.childNodes.filter((n) => n instanceof FakeElement);
67	  }
68	
69	  toNodes(items) {
70	    return items.map((item) => {
71	      if (typeof item === 'string') return new TextNode(item);
72	      const el = this.page.unwrap(item);
73	      if (!el) throw new TypeError('append/replaceChildren got a non-node');
74	      return el;
75	    });
76	  }
77	
78	  append(...items) {
79	    this.childNodes = [...this.childNodes, ...this.toNodes(items)];
80	  }
81	
82	  replaceChildren(...items) {
83	    this.childNodes = this.toNodes(items);
84	  }
85	
86	  addEventListener(type, fn) {
87	    this.listeners[type] = [...(this.listeners[type] ?? []), fn];
88	  }
89	
90	  /** Test-side: fire an event; resolves to the event (see `defaultPrevented`). */
91	  dispatch(type) {
92	    const event = { type, defaultPrevented: false, preventDefaultCalls: 0 };
93	    const exposed = this.page.wrap(
94	      { preventDefault: () => { event.defaultPrevented = true; event.preventDefaultCalls += 1; } },
95	      `${type} event`, new Set(['preventDefault']),
96	    );
97	    for (const fn of this.listeners[type] ?? []) fn.call(this.proxy, exposed);
98	    return event;
99	  }
100	
101	  /** Test-side: a click is dispatched like the browser, except disabled buttons get none. */
102	  click() {
103	    return this.dispatch('click');
104	  }
105	}
106	
107	function makeResponse(page, status, json) {
108	  return page.wrap({ status, json }, 'response', new Set(['status', 'json']));
109	}
110	
111	/** One recorded fetch call, settled by the test. */
112	class FetchCall {
113	  constructor(page, url, options) {
114	    this.page = page;
115	    this.url = url;
116	    this.options = options;
117	    this.method = options?.method ?? 'GET';
118	    this.promise = new Promise((resolve, reject) => {
119	      this.resolveFetch = resolve;
120	      this.rejectFetch = reject;
121	    });
122	  }
123	
124	  /** Reply with a status and a JSON-able body (json() resolves to a copy). */
125	  reply(status, body) {
126	    const copy = body === undefined ? undefined : JSON.parse(JSON.stringify(body));
127	    const json = () => (body === undefined
128	      ? Promise.reject(new SyntaxError('Unexpected end of JSON input'))
129	      : Promise.resolve(copy));
130	    this.resolveFetch(makeResponse(this.page, status, json));
131	  }
132	
133	  /** Reply whose body is not JSON: json() rejects. */
134	  replyNotJson(status) {
135	    this.resolveFetch(makeResponse(this.page, status, () => Promise.reject(new SyntaxError('bad json'))));
136	  }
137	
138	  /** Reply whose body arrives later: returns { send(body), fail() }. */
139	  replyLater(status) {
140	    let settle;
141	    const bodyPromise = new Promise((resolve, reject) => { settle = { resolve, reject }; });
142	    this.resolveFetch(makeResponse(this.page, status, () => bodyPromise));
143	    return {
144	      send: (body) => settle.resolve(JSON.parse(JSON.stringify(body))),
145	      fail: () => settle.reject(new TypeError('body stream failed')),
146	    };
147	  }
148	
149	  /** No reply at all (network error). */
150	  fail() {
151	    this.rejectFetch(new TypeError('Failed to fetch'));
152	  }
153	}
154	
155	class FakePage {
156	  constructor() {
157	    this.violations = [];
158	    this.log = [];
159	    this.fetches = [];
160	    this.proxies = new WeakMap();
161	    this.elements = new Map();
162	    for (const [id, tag, type] of PAGE_ELEMENTS) {
163	      this.elements.set(id, new FakeElement(this, tag, { id, type }));
164	    }
165	  }
166	
167	  el(id) {
168	    return this.elements.get(id);
169	  }
170	
171	  unwrap(proxy) {
172	    return this.proxies.get(proxy);
173	  }
174	
175	  /** Wraps a target so the script may use only `allowed` members; logs sets and calls. */
176	  wrap(target, label, allowed) {
177	    const page = this;
178	    const proxy = new Proxy(target, {
179	      get(t, prop) {
180	        if (typeof prop === 'symbol' || prop === 'then') return undefined;
181	        if (!allowed.has(prop)) return page.violate(`get ${label}.${prop}`);
182	        const value = t[prop];
183	        if (typeof value !== 'function') return value;
184	        return (...args) => {
185	          page.log.push(`${label}.${prop}()`);
186	          return value.apply(t, args);
187	        };
188	      },
189	      set(t, prop, value) {
190	        if (typeof prop === 'symbol' || !allowed.has(prop)) return page.violate(`set ${label}.${String(prop)}`);
191	        page.log.push(`${label}.${prop}=${JSON.stringify(value)}`);
192	        t[prop] = value;
193	        return true;
194	      },
195	      has: (t, prop) => allowed.has(prop),
196	      deleteProperty: (t, prop) => page.violate(`delete ${label}.${String(prop)}`),
197	      defineProperty: (t, prop) => page.violate(`define ${label}.${String(prop)}`),
198	    });
199	    this.proxies.set(proxy, target);
200	    return proxy;
201	  }
202	
203	  violate(what) {
204	    this.violations.push(what);
205	    throw new Error(`app.js used a forbidden API: ${what}`);
206	  }
207	
208	  makeDocument() {
209	    const doc = {
210	      getElementById: (id) => this.elements.get(id)?.proxy ?? null,
211	      createElement: (tag) => new FakeElement(this, String(tag).toLowerCase()).proxy,
212	    };
213	    return this.wrap(doc, 'document', new Set(['getElementById', 'createElement']));
214	  }
215	
216	  makeFetch() {
217	    return (url, options) => {
218	      const call = new FetchCall(this, url, options);
219	      this.log.push(`fetch ${call.method} ${url}`);
220	      this.fetches.push(call);
221	      return call.promise;
222	    };
223	  }
224	
225	  /** Fetch calls whose URL is a bookings list request. */
226	  listFetches() {
227	    return this.fetches.filter((f) => f.method === 'GET' && /^\/api\/bookings(\?|$)/.test(f.url));
228	  }
229	
230	  lastFetch() {
231	    return this.fetches[this.fetches.length - 1];
232	  }
233	}
234	
235	/**
236	 * Loads public/app.js (or `source`) into a fresh fake page. The script's only
237	 * globals are `document` and `fetch` (plus the JS built-ins).
238	 */
239	export function loadApp({ source = readFileSync(APP_PATH, 'utf8'), setup } = {}) {
240	  const page = new FakePage();
241	  if (setup) setup(page);
242	  const context = vm.createContext({ document: page.makeDocument(), fetch: page.makeFetch() });
243	  new vm.Script(source, { filename: 'app.js' }).runInContext(context);
244	  return page;
245	}
246	
247	/** Lets every pending promise chain run to the end. */
248	export async function flush() {
249	  for (let i = 0; i < 5; i += 1) await new Promise((resolve) => setImmediate(resolve));
250	}
251	
252	/** Text of each child node of an element, as [kind, text] pairs. */
253	export const describeChildren = (el) =>
254	  el.childNodes.map((n) => (n instanceof TextNode ? ['text', n.data] : [n.tag, n.textContent]));
255

